import openpyxl, subprocess, glob

base = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind'

def read_xlsx_summary(path):
    print('====================================')
    print('XLSX:', path)
    wb = openpyxl.load_workbook(path, data_only=True)
    for name in wb.sheetnames:
        print('--- Sheet:', name)
        ws = wb[name]
        rows = list(ws.iter_rows(values_only=True))
        for r in rows[:5]:
            if any(r): print([str(c) if c is not None else '' for c in r[:12]])
        if len(rows) > 5:
            print('... total rows:', len(rows))
            for r in rows[-5:]:
                if any(r): print([str(c) if c is not None else '' for c in r[:12]])

read_xlsx_summary(base + '/30_drawings/E-701_Panelboard_Schedules_RevC.xlsx')

wb = openpyxl.load_workbook(base + '/40_studies/GLC-01_Generator_Load_Calculation.xlsx', data_only=True)
for name in wb.sheetnames:
    print('--- GLC-01 Sheet:', name)
