refl = {}
for row in list(ws_a.iter_rows(values_only=True))[1:]:
    if row[0]:
        rm = str(row[0]).strip()
        refl[rm] = (row[1], float(row[6]), float(row[7]), float(row[8]))

wb_e = openpyxl.load_workbook(base + '/30_drawings/E-501_Luminaire_Schedule_RevC.xlsx', data_only=True)
ws_e = wb_e['Luminaires']
lum_info = {}
for row in list(ws_e.iter_rows(values_only=True))[1:]:
    if row[0] and row[0] in ('L1', 'L2', 'L3', 'L4', 'L5'):
        lum_info[row[0]] = (float(row[4]), base + '/' + row[10])

ies_data = {}
for ltype, (watts, path) in lum_info.items():
    with open(path) as f:
        lines = [l.strip() for l in f if l.strip()]
    idx = lines.index('TILT=NONE')
    header_nums = []
    for l in lines[idx+1:]:
        header_nums.extend(float(x) for x in l.split())
    n_v = int(header_nums[3])
    n_h = int(header_nums[4])
    v_angles = header_nums[13:13+n_v]
    h_angles = header_nums[13+n_v:13+n_v+n_h]
    rem = header_nums[13+n_v+n_h:]
    candelas = []
    for h_i in range(n_h):
        candelas.append(rem[h_i*n_v:(h_i+1)*n_v])
    ibar = []
    for v_i in range(n_v):
        if n_h == 1:
            ibar.append(candelas[0][v_i])
        else:
            s = 0.0
            for h_i in range(n_h - 1):
                a, b = h_angles[h_i], h_angles[h_i+1]
                ia, ib = candelas[h_i][v_i], candelas[h_i+1][v_i]
                s += 0.5 * (ia + ib) * (b - a)
            ibar.append(s / (h_angles[-1] - h_angles[0]))
    flux = 0.0
    for v_i in range(n_v - 1):
        t1 = math.radians(v_angles[v_i])
        t2 = math.radians(v_angles[v_i+1])
        flux += 2.0 * math.pi * (math.cos(t1) - math.cos(t2)) * 0.5 * (ibar[v_i] + ibar[v_i+1])
    ies_data[ltype] = (watts, v_angles, h_angles, candelas, flux)

