import xml.etree.ElementTree as ET, re

base = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind/20_guide_specifications/UFGS_Division_26_SpecsIntact'

def get_ttl(elem):
    ttl = elem.find('TTL')
    if ttl is None: return ''
    return re.sub(r'\s+', ' ', ''.join(ttl.itertext())).strip()

def dump_tree(filename):
    with open(base + '/' + filename, 'rb') as f:
        root = ET.fromstring(f.read())
    print('====================================')
    print('FILE:', filename)
    p_idx = 0
    for child in root:
        if child.tag == 'PRT':
            p_idx += 1
            print(f'{get_ttl(child)}')
            def walk_spt(parent, prefix):
                s_idx = 0
                for c in parent:
                    if c.tag == 'SPT':
                        s_idx += 1
                        num = f'{prefix}.{s_idx}'
                        print(f'  {num} {get_ttl(c)}')
                        walk_spt(c, num)
                    elif c.tag == 'TAI':
                        opt = c.attrib.get('OPT', '')
                        if opt == 'ARMY':
                            for tc in c:
